/* cppi::11bda7f1e12de715e22f0e1761a25db9f9829ab64b4707764aabd4837ebc62f6 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-17' and end_date = '2025-04-17')
and start_date = '2025-04-17' and end_date = '2025-04-17'

